    DB 8Eh, 0C0h    ; MOV DS1, AW
    DB 26h, 0C6h, 06h, 0E1h, 0FFh, 0ECh    ; MOV byte DS1:[FFE1h], ECh
; ---- window 0: WTC 0000h PMC1 80h (code 0 data 0 io 0 PMC1 80) 
    DB 26h, 0C6h, 06h, 0Ah, 0FFh, 80h    ; MOV byte DS1:[FF0Ah], 80h
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 00h, 00h    ; MOV word DS1:[FFE8h], 0000h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 53h, 00h    ; CALL probe
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 0EFh    ; OUT DW, AW
; ---- window 1: WTC 8008h PMC1 80h (code 0 data 2 io 2 PMC1 80) 
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 08h, 80h    ; MOV word DS1:[FFE8h], 8008h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 01h, 00h    ; MOV AW, 0001h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 3Bh, 00h    ; CALL probe
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 01h, 00h    ; MOV AW, 0001h
    DB 0EFh    ; OUT DW, AW
; ---- window 2: WTC C00Ch PMC1 80h (code 0 data 3 io 3 PMC1 80) READY: data and I/O
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 0Ch, 0C0h    ; MOV word DS1:[FFE8h], C00Ch
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 02h, 00h    ; MOV AW, 0002h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 23h, 00h    ; CALL probe
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 02h, 00h    ; MOV AW, 0002h
    DB 0EFh    ; OUT DW, AW
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 0FFh, 0FFh    ; MOV word DS1:[FFE8h], FFFFh
    DB 26h, 0C6h, 06h, 0Ah, 0FFh, 00h    ; MOV byte DS1:[FF0Ah], 00h
    DB 0BAh, 00h, 0FFh    ; MOV DW, FF00h
    DB 0EEh    ; OUT DW, AL
    DB 0F4h    ; HALT
done:
    DB 0EBh, 0FEh    ; BR done
fail:
    DB 0BAh, 02h, 0FFh    ; MOV DW, FF02h
    DB 0EEh    ; OUT DW, AL
    DB 0F4h    ; HALT
fspin:
